-- GENERATED by 'ira_import --print-schema' from backend/src/database.c (single source of truth).
-- Do not edit by hand: change database.c and regenerate.
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS import_metadata (
  id               INTEGER PRIMARY KEY,
  dataset_version  TEXT NOT NULL,
  source           TEXT NOT NULL,
  import_time      INTEGER NOT NULL,
  node_count       INTEGER NOT NULL CHECK (node_count >= 0),
  edge_count       INTEGER NOT NULL CHECK (edge_count >= 0),
  import_status    TEXT NOT NULL CHECK (import_status IN ('ok','warnings','failed')),
  report_json      TEXT
);

CREATE TABLE IF NOT EXISTS places (
  place_id    INTEGER PRIMARY KEY,
  osm_id      INTEGER,
  name        TEXT NOT NULL,
  name_en     TEXT,
  type        TEXT NOT NULL,
  type_rank   INTEGER NOT NULL DEFAULT 9,
  state       TEXT,
  district    TEXT,
  near        TEXT,
  latitude    REAL NOT NULL CHECK (latitude BETWEEN -90 AND 90),
  longitude   REAL NOT NULL CHECK (longitude BETWEEN -180 AND 180),
  population  INTEGER
);
CREATE INDEX IF NOT EXISTS idx_places_type ON places(type_rank);
CREATE VIRTUAL TABLE IF NOT EXISTS places_fts USING fts5(
  name, name_en, state, district, content='places', content_rowid='place_id',
  tokenize='unicode61 remove_diacritics 2'
);

CREATE TABLE IF NOT EXISTS road_incidents (
  incident_id         INTEGER PRIMARY KEY,
  incident_type       TEXT NOT NULL CHECK (incident_type IN
                        ('accident','closure','congestion','roadwork','hazard')),
  latitude            REAL NOT NULL CHECK (latitude BETWEEN -90 AND 90),
  longitude           REAL NOT NULL CHECK (longitude BETWEEN -180 AND 180),
  affected_edge_id    INTEGER,
  both_directions     INTEGER NOT NULL DEFAULT 1,
  dataset_version     TEXT,
  reported_time       INTEGER NOT NULL,
  expiry_time         INTEGER NOT NULL CHECK (expiry_time > reported_time),
  verification_status TEXT NOT NULL CHECK (verification_status IN
                        ('pending','verified','rejected','expired')),
  simulated           INTEGER NOT NULL DEFAULT 0,
  description         TEXT
);
CREATE INDEX IF NOT EXISTS idx_incidents_expiry ON road_incidents(expiry_time);

CREATE TABLE IF NOT EXISTS traffic_observations (
  observation_id         INTEGER PRIMARY KEY,
  edge_id                INTEGER NOT NULL,
  latitude               REAL,
  longitude              REAL,
  observed_time          INTEGER NOT NULL,
  estimated_time_seconds REAL NOT NULL CHECK (estimated_time_seconds > 0),
  source                 TEXT NOT NULL,
  provider               TEXT,
  confidence             REAL NOT NULL CHECK (confidence BETWEEN 0 AND 1),
  expiry_time            INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_obs_edge ON traffic_observations(edge_id, expiry_time);

-- Optional export of the routing graph for inspection (importer --export-edges).
-- The server routes from graph.bin, not from these tables.
CREATE TABLE IF NOT EXISTS road_nodes (
  node_id        INTEGER PRIMARY KEY,
  latitude       REAL NOT NULL,
  longitude      REAL NOT NULL,
  source_node_id INTEGER
);
CREATE TABLE IF NOT EXISTS road_edges (
  edge_id             INTEGER PRIMARY KEY,
  source_node_id      INTEGER NOT NULL REFERENCES road_nodes(node_id),
  target_node_id      INTEGER NOT NULL REFERENCES road_nodes(node_id),
  distance_meters     REAL NOT NULL CHECK (distance_meters > 0),
  baseline_time_seconds REAL NOT NULL CHECK (baseline_time_seconds > 0),
  road_type           TEXT NOT NULL,
  speed_limit         INTEGER,
  access_flags        INTEGER NOT NULL DEFAULT 0,
  one_way             INTEGER NOT NULL DEFAULT 0,
  geometry_reference  INTEGER
);
CREATE INDEX IF NOT EXISTS idx_edges_source ON road_edges(source_node_id);
CREATE INDEX IF NOT EXISTS idx_edges_target ON road_edges(target_node_id);
